src/interfaces/IVeHemi.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.29;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {IERC721Enumerable} from "@openzeppelin/contracts/token/ERC721/extensions/IERC721Enumerable.sol";
import {IVeHemiVoteDelegation} from "./IVeHemiVoteDelegation.sol";
import {IRewardDistributor} from "./IRewardDistributor.sol";

interface IVeHemi is IERC721Enumerable {
    // --- Structs ---
    struct Point {
        int128 bias;
        int128 slope;
        uint64 timestamp;
        uint64 blockNumber;
        uint128 amount;
        uint256 fixedBias; // for v2+ use
    }

    struct UserPoint {
        Point point;
        address owner;
    }

    struct LockedBalance {
        int128 amount;
        uint64 end;
    }

    // --- Events ---
    event Deposit(
        address indexed provider,
        uint256 indexed tokenId,
        uint256 amount,
        uint256 lockTime,
        uint256 timestamp
    );

    event Withdraw(
        address indexed provider,
        uint256 indexed tokenId,
        uint256 amount,
        uint256 timestamp
    );
    event Lock(
        address indexed provider,
        address indexed account,
        uint256 indexed tokenId,
        uint256 amount,
        uint256 start,
        uint256 lockTime,
        uint256 extraData,
        bool transferable,
        bool forfeitable
    );
    event Checkpoint(uint256 epoch, uint256 tokenId, LockedBalance oldLock, LockedBalance newLock);

    event VoteDelegationUpdated(
        IVeHemiVoteDelegation indexed oldVoteDelegation,
        IVeHemiVoteDelegation indexed newVoteDelegation
    );

    event RewardDistributorUpdated(
        IRewardDistributor indexed oldRewardDistributor,
        IRewardDistributor indexed newRewardDistributor
    );

    event ForfeitAdminUpdated(address indexed oldForfeitAdmin, address indexed newForfeitAdmin);

    // --- V2 Events ---
    event LockedSeedingFinalized(uint256 epoch);
    event RewardUpdateFailed(uint256 indexed tokenId);
    event DelegationUpdateFailed(uint256 indexed delegator);
    /// @notice Emitted by `markSeedingStarted` once the seeding window opens.
    ///         `seedingTargetId` is the exclusive upper bound for `seedBatch`.
    ///         The per-batch accumulator (`_seedingProgress`) is internal so
    ///         operators monitoring progress mid-flow should probe its storage
    ///         slots directly (slots 23-26; see VeHemiStorageV2 layout block).
    ///         `finalizeSeeding` emits the terminating `LockedSeedingFinalized`.
    event SeedingStarted(uint256 seedingTargetId);

    // --- Errors ---
    // Declared in VeHemi.sol (not here) to avoid Solidity duplicate-identifier
    // conflicts when both IVeHemi and VeHemi are imported in the same compilation unit.
    // Errors are included in VeHemi's ABI and can be decoded from revert data.
    //
    // AddressIsNull, AmountIsZero, AmountTooSmall, ForfeitWindowExpired,
    // InvalidConfiguration, LockDurationTooLong, LockDurationTooShort, LockExpired,
    // LockNotExpired, NewLockDurationNotGreater, NoExistingLock, NotForfeitAdmin,
    // NotForfeitable, NotOwner, NotTransferable, OwnerIsZero,
    // SeedingAlreadyFinalized, SeedingAlreadyStarted, SeedingNotStarted,
    // SeedingInProgress, SeedingIncomplete

    // --- External/Public Functions ---
    function HEMI() external view returns (IERC20);
    function initialize(address owner) external;
    function checkpoint() external;
    function createLock(uint256 amount, uint256 lockDuration) external returns (uint256 tokenId);
    function createLockFor(
        uint256 amount,
        uint256 lockDuration,
        address account,
        bool transferable,
        bool forfeitable
    ) external returns (uint256 tokenId);
    function increaseAmount(uint256 tokenId, uint256 amount) external;
    function increaseUnlockTime(uint256 tokenId, uint256 lockDuration) external;
    function withdraw(uint256 tokenId) external;
    function forfeit(uint256 tokenId) external;
    function getUserPoint(uint256 tokenId, uint256 epoch) external view returns (UserPoint memory);
    function getGlobalPoint(uint256 epoch) external view returns (Point memory);
    function getLockedBalance(uint256 tokenId) external view returns (LockedBalance memory);
    function isTransferable(uint256 tokenId) external view returns (bool);
    function totalLocked() external view returns (uint256);
    function epoch() external view returns (uint256);
    function userPointEpoch(uint256 tokenId) external view returns (uint256);
    function nextTokenId() external view returns (uint256);
    function provider(uint256 tokenId) external view returns (address);
    function transferableAfter(uint256 tokenId) external view returns (uint256);
    function forfeitable(uint256 tokenId) external view returns (bool);
    function forfeitAdmin() external view returns (address);
    function slopeChanges(uint256 timestamp) external view returns (int128);
    function balanceOfNFT(uint256 tokenId) external view returns (uint256);
    function balanceOfNFTAt(uint256 tokenId, uint256 timestamp) external view returns (uint256);
    function balanceAndOwnerOfNFTAt(
        uint256 tokenId,
        uint256 timestamp
    ) external view returns (uint256, address);
    function totalVeHemiSupply() external view returns (uint256);
    function totalVeHemiSupplyAt(uint256 timestamp_) external view returns (uint256);

    // --- V2 Locked + Forfeitable Curve Functions ---
    function markSeedingStarted() external;
    function seedBatch(uint256 maxIterations) external;
    function finalizeSeeding() external;
    function seedingStarted() external view returns (bool);
    function seedingStartedAt() external view returns (uint64);
    function seedingTargetId() external view returns (uint256);
    /// @notice Last token ID processed by `seedBatch`. Off-chain seeding drivers
    ///         poll this to detect cursor completion without depending on the
    ///         private `_seedingProgress` storage slot index.
    function seedingCursor() external view returns (uint256);
    function nonTransferableTotalVeHemiSupply() external view returns (uint256);
    function nonTransferableTotalVeHemiSupplyAt(uint256 timestamp) external view returns (uint256);
    function forfeitableTotalVeHemiSupply() external view returns (uint256);
    function forfeitableTotalVeHemiSupplyAt(uint256 timestamp) external view returns (uint256);
    function supplyBreakdown() external view returns (uint256 total, uint256 locked_, uint256 forfeitable_, uint256 transferable);
    // lockedSeedingFinalized(), lockedSlopeChanges(uint256), and forfeitableSlopeChanges(uint256)
    // are exposed as public state variables via VeHemiStorageV2 (auto-generated getters).
}

src/interfaces/IVeHemiVoteDelegation.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.29;

/// @dev KNOWN LIMITATION — uint64 slope fields
///      The `slope` (uint64) fields in Delegation, DelegateCheckpoint, and Expiration
///      overflow when a single position or aggregate delegation exceeds ~2.328 billion
///      HEMI (slope = amount / MAX_TIME; uint64 max ≈ 1.844e19; threshold ≈ 2.328e27 wei).
///      With 10B total supply, this caps effective delegation at ~23.3% of supply per
///      delegatee. Overflow causes a clean SafeCast revert (not silent corruption).
///      The struct slots are maximally packed (32B each) — slope cannot be widened without
///      adding a storage slot, which would corrupt existing proxy data. A future V2
///      delegation contract with wider types can be deployed and activated via
///      VeHemi.updateVoteDelegation(). See also: uint96 bias overflow at ~5.35B HEMI
///      (current era, time-dependent, secondary to slope).
interface IVeHemiVoteDelegation {
    struct Delegation {
        address delegatee;
        uint48 end;
        uint96 bias;
        uint96 amount;
        uint64 slope; // see KNOWN LIMITATION above — overflows at ~2.328B HEMI
    }

    /// A representation of a delegate and all its delegators at a particular timestamp
    struct DelegateCheckpoint {
        uint128 normalizedBias;
        uint128 fixedBias; // for v2+ use
        uint128 totalAmount;
        uint64 normalizedSlope; // see KNOWN LIMITATION above — aggregate overflow at ~2.328B HEMI per delegatee
        uint64 timestamp;
    }

    /// Represents the total bias, slope, and Hemi amount of all accounts that expire for a specific delegate
    /// in a particular SIX_DAYS bucket (YEAR/60 ≈ 6.0875 days — not a calendar week).
    struct Expiration {
        uint96 bias;
        uint96 amount;
        uint64 slope; // see KNOWN LIMITATION above
    }

    // Only used in memory
    struct NormalizedVeHemiLockInfo {
        uint256 bias;
        uint256 slope;
        uint256 amount;
        uint256 end;
    }

    /**
     * @dev Emitted when an account changes their delegate.
     */
    event DelegateChanged(
        uint256 indexed delegator,
        address indexed fromDelegatee,
        address indexed toDelegatee
    );

    /**
     * @dev Emitted when a token transfer or delegate change results in changes to a delegate's number of voting units.
     */
    event DelegateVotesChanged(address indexed delegatee, uint256 previousVotes, uint256 newVotes);

    /**
     * @dev Emitted when the trusted adapter is changed via setTrustedAdapter.
     */
    event TrustedAdapterUpdated(address indexed oldAdapter, address indexed newAdapter);

    /**
     * @dev Emitted when an account's auto-delegate target changes via
     *      setAutoDelegate, clearAutoDelegate, or delegateAllFor (which
     *      sets it as a side effect). Indexers can reconstruct the
     *      account → auto-delegate mapping from this event stream alone.
     */
    event AutoDelegateSet(
        address indexed owner,
        address indexed previousDelegate,
        address indexed newDelegate
    );

    function delegate(uint256 delegator_, address delegatee_) external;

    function delegation(uint256 tokenId_) external view returns (Delegation memory);

    function getVotes(address account_) external view returns (uint256);

    function getPastVotes(address account_, uint256 timestamp_) external view returns (uint256);

    /// @notice Returns the auto-delegate address for an account. When set, new veHEMI
    ///         positions created for this account will be automatically delegated to
    ///         this address instead of self-delegating.
    function autoDelegate(address account_) external view returns (address);

    function clearAutoDelegate() external;

    /// @notice Set the caller's auto-delegate target without iterating their
    ///         existing positions. New positions minted to the caller after
    ///         this call will auto-delegate to `delegatee_`. Existing
    ///         positions retain their current delegations until explicitly
    ///         re-delegated (per-tokenId via `delegate`, or in bulk via the
    ///         adapter's `delegate(address)` which proxies to `delegateAllFor`).
    /// @dev Use case: users with too many positions to fit a `delegateAllFor`
    ///      call within a block can still set their auto-delegate target so
    ///      newly-minted positions go to the right place. Combine with
    ///      per-tokenId `delegate()` calls to migrate existing positions
    ///      incrementally.
    function setAutoDelegate(address delegatee_) external;

    function refreshVotingPower(address delegatee_) external;

    function refreshVotingPowerBatch(address[] calldata delegatees_) external;

    // ─── Legacy state import ─────────────────────────────────────────────

    /// @notice Emitted when a legacy per-tokenId delegation is imported from
    ///         an older VeHemiVoteDelegation contract into this one as part
    ///         of an `updateVoteDelegation` migration.
    event LegacyDelegationImported(
        uint256 indexed tokenId, address indexed delegatee, address indexed legacy
    );

    /// @notice Emitted when a legacy `autoDelegate[owner]` value is imported.
    event LegacyAutoDelegateImported(
        address indexed owner, address indexed delegatee, address indexed legacy
    );

    /// @notice One-time flip to `true` when the migration window is sealed.
    event MigrationFinalizedEvent();

    /// @notice Replay per-tokenId delegations from a legacy VeHemiVoteDelegation
    ///         contract into this contract's storage. Owner-only (the VeHemi
    ///         owner). Idempotent. Reverts after `finalizeMigration()`.
    function importDelegationsFromLegacy(
        IVeHemiVoteDelegation legacy_, uint256[] calldata tokenIds_
    ) external;

    /// @notice Replay per-owner `autoDelegate` config from a legacy contract.
    ///         Owner-only. Idempotent. Reverts after `finalizeMigration()`.
    function importAutoDelegatesFromLegacy(
        IVeHemiVoteDelegation legacy_, address[] calldata owners_
    ) external;

    /// @notice Permanently seal the import functions. One-way latch.
    function finalizeMigration() external;

    /// @notice Whether `finalizeMigration()` has been called.
    function migrationFinalized() external view returns (bool);
}

